const presenceSafeKey = (value = '') => String(value || 'unknown').replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 120) || 'unknown';
const presenceDeviceType = () => {
  if (typeof navigator === 'undefined') return 'server';
